SELECT club_type as type, COUNT(*) AS count FROM club_mgmt WHERE deleted = 0
AND apply_time between #{startTime} AND #{endTime}
GROUP BY club_type

SELECT DATE_FORMAT(apply_time, '%Y-%m') AS month, COUNT(*) AS count FROM club_mgmt WHERE deleted = 0
AND apply_time between #{startTime} AND #{endTime}
GROUP BY month

SELECT club_name AS clubName, COUNT(student_id) AS memberCount,club_type as clubType FROM club_mgmt WHERE deleted = 0
AND apply_time between #{startTime} AND #{endTime}
GROUP BY club_name,club_type

SELECT club_type AS name, COUNT(student_id) AS count FROM club_mgmt WHERE deleted = 0
AND apply_time between #{startTime} AND #{endTime}
GROUP BY club_type
